rollback.sql:
DROP PROCEDURE IF EXISTS BT.SP_RESERVE_API_CALL(
    IN INTEGER,
    OUT TEXT, OUT TEXT, OUT TEXT
);

changeSet.sql:
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'quant_app') THEN
        GRANT EXECUTE ON PROCEDURE BT.SP_RESERVE_API_CALL(
            IN INTEGER,
            OUT TEXT, OUT TEXT, OUT TEXT
        ) TO quant_app;
    END IF;
END $$;
